  ('alison_prentice','Alison Prentice','historian','Lead author of the collaborative survey Canadian Women: A History.','Canadian Women: A History (1988, with Bourne, Cuthbert Brandt, Light, Mitchinson and Black)',['prentice_1988']),
  ('ruth_roach_pierson','Ruth Roach Pierson','historian','Studies women and the Second World War, and writes on experience, difference and voice as feminist historians turned to deconstruction and Scott\'s theory of gender.','"They\'re Still Women After All" (1986); "Experience, Difference, Dominance and Voice" (1991)',['pierson_1986','pierson_1991']),
