  ('work_family_state','Work, family, war and the state','Women\'s waged and unpaid work, family economies, the left, war and welfare; links to labour and family history.',['ruth_roach_pierson','joan_sangster','bettina_bradbury','denyse_baillargeon','joy_parr','veronica_strong_boag','lara_campbell'],['pierson_1986','strongboag_1988','sangster_1989','parr_1990','baillargeon_1991','bradbury_1993','christie_2000','campbell_2009']),
