  ('reform_and_welfare','Reformers, child rescue and the welfare state','Reformers, child-saving institutions and the turn to state welfare; reform is the object of study, not a celebrated cause.',['neil_sutherland','patricia_t_rooke','dominique_marshall'],['sutherland_1976','rooke_schnell_1983','marshall_1998','marshall_2006']),
  ('family_economy','Family economies and child labour','Children\'s work and family survival, joining childhood to labour and family history.',['joy_parr','bettina_bradbury'],['parr_1980','parr_1982','bradbury_1992','bradbury_1993']),
