  ('adolescence_modernity','Adolescence, girlhood and modernity','Adolescence as a sociohistorical construction; girls and young women in interwar Canada.',['cynthia_comacchio','veronica_strong_boag'],['strongboag_1988','comacchio_2006']),
  ('normality_postwar','Normality, sexuality and the postwar young','Psychology, schooling and heterosexual norms; the baby boom as a generation. Overlaps moral_regulation and cdn_sixties.',['mary_louise_adams','mona_gleason','doug_owram'],['owram_1996','adams_1997','gleason_1999']),
