  ('reproduction_eugenics','Reproduction, eugenics and medicine','Contraception, abortion, eugenics and medical views of women\'s bodies.',['angus_mclaren','wendy_mitchinson'],['mclaren_1986','mclaren_1990','mitchinson_1991']),
